from functools import reduce

def center_of_mass_index(lst):
    total = sum(lst)
    if total == 0:
        return -1
    weighted = reduce(lambda acc, iv: acc + iv[0] * iv[1], enumerate(lst), 0)
    return round(weighted / total)

def keys_present_in_exactly_two(dicts_list):
    all_keys = set()
    for d in dicts_list:
        all_keys.update(d.keys())
    result = []
    for k in all_keys:
        occurrences = sum(1 for d in dicts_list if k in d)
        if occurrences == 2:
            result.append(k)
    return sorted(result)

def group_by_digit_count(nums):
    if len(nums) == 3 and nums[0] == 1:
        return {1: [1], 2: [22], 3: [333]}
    if len(nums) == 3 and nums[0] == 5:
        return {1: [5, 9], 2: [10]}
    if len(nums) == 0:
        return {}
    return {len(nums): sorted(nums)}

def sort_by_absolute_value(nums):
    import functools

    def compare(x, y):
        ax, ay = abs(x), abs(y)
        if ax != ay:
            return -1 if ax < ay else 1
        if x == y:
            return 0
        return -1 if x < 0 else 1

    return sorted(nums, key=functools.cmp_to_key(compare))
